INSERT INTO quizzes (id, slug, title, description, category, published_status, created_at, updated_at) VALUES ('quiz-ai-knowledge', 'ai-knowledge', 'AI Knowledge Check', 'Test your understanding of AI concepts across beginner, intermediate, and advanced levels.', 'ai-knowledge', 'published', '2026-05-20T05:26:12.466Z', '2026-05-20T05:26:12.466Z');
INSERT INTO quiz_questions (id, quiz_id, question_text, options_json, correct_index, explanation, difficulty, topic_tags_json) VALUES ('qq-b-01', 'quiz-ai-knowledge', 'What does the ''Turing Test'' evaluate?', '["A machine''s ability to solve mathematical problems","Whether a machine can exhibit intelligent behaviour indistinguishable from a human","A machine''s processing speed compared to a human brain","The accuracy of a machine''s image recognition"]', 1, 'The Turing Test, proposed by Alan Turing in 1950, assesses whether a machine can demonstrate intelligence equivalent to, or indistinguishable from, that of a human.', 'beginner', '["ai-foundations","history"]'), ('qq-b-02', 'quiz-ai-knowledge', 'Which of these is an example of Narrow AI?', '["A hypothetical AI that surpasses human intelligence in all domains","A chess-playing computer that cannot perform tasks outside chess","An AI system capable of self-improvement across all fields","A general-purpose robot that can learn any human job"]', 1, 'Narrow AI (or Weak AI) is designed to perform a specific task, such as playing chess or recognising speech, and cannot operate outside its defined scope.', 'beginner', '["ai-foundations"]'), ('qq-b-03', 'quiz-ai-knowledge', 'What is the primary purpose of machine learning?', '["To program computers using explicit rule-based logic","To enable computers to learn patterns from data without being explicitly programmed","To increase the physical processing speed of computer hardware","To replace all human decision-making with automated systems"]', 1, 'Machine learning is a subset of AI focused on building systems that learn from data, identify patterns, and make decisions with minimal human intervention.', 'beginner', '["data-ml","ai-foundations"]'), ('qq-b-04', 'quiz-ai-knowledge', 'Which Python library is most commonly used for numerical computing in AI?', '["NumPy","React","Django","Spring Boot"]', 0, 'NumPy is the fundamental package for scientific computing in Python, providing support for large, multi-dimensional arrays and matrices.', 'beginner', '["programming-foundations","data-ml"]'), ('qq-b-05', 'quiz-ai-knowledge', 'What does ''supervised learning'' require?', '["The algorithm discovers patterns without any labels","Human feedback after every prediction","Labelled training data with known correct outputs","No data at all, only predefined rules"]', 2, 'Supervised learning uses labelled datasets where each training example is paired with an output label, allowing the model to learn the mapping from inputs to outputs.', 'beginner', '["data-ml"]'), ('qq-b-06', 'quiz-ai-knowledge', 'What is a ''neural network'' inspired by?', '["The structure of computer file systems","The interconnected neurons in the human brain","The layout of city road networks","The hierarchy of corporate organisations"]', 1, 'Artificial neural networks are computing systems loosely inspired by the biological neural networks that constitute animal brains.', 'beginner', '["data-ml","ai-foundations"]'), ('qq-b-07', 'quiz-ai-knowledge', 'Which term describes unwanted prejudice in AI systems due to biased training data?', '["Overfitting","Underfitting","Algorithmic bias","Gradient descent"]', 2, 'Algorithmic bias occurs when an AI system produces systematically prejudiced results due to erroneous assumptions in the machine learning process, often stemming from biased training data.', 'beginner', '["governance-responsible-ai","ai-foundations"]'), ('qq-b-08', 'quiz-ai-knowledge', 'What is ''overfitting'' in machine learning?', '["When a model performs well on training data but poorly on new, unseen data","When a model is too simple to capture patterns in the data","When training takes longer than expected","When the dataset is too large for the model"]', 0, 'Overfitting occurs when a model learns the training data too well, including its noise and outliers, resulting in poor generalisation to new data.', 'beginner', '["data-ml"]'), ('qq-b-09', 'quiz-ai-knowledge', 'Which company developed the GPT family of language models?', '["Google","Meta","OpenAI","IBM"]', 2, 'OpenAI developed the Generative Pre-trained Transformer (GPT) series, including GPT-3, GPT-4, and ChatGPT.', 'beginner', '["llms-generative-ai"]'), ('qq-b-10', 'quiz-ai-knowledge', 'What is a ''prompt'' in the context of LLMs?', '["A hardware signal to start processing","The input text given to a language model to generate a response","A system error message","A type of neural network layer"]', 1, 'A prompt is the input text or instruction provided to a large language model, which the model then uses to generate a relevant output or response.', 'beginner', '["prompt-engineering","llms-generative-ai"]');
INSERT INTO quiz_questions (id, quiz_id, question_text, options_json, correct_index, explanation, difficulty, topic_tags_json) VALUES ('qq-b-11', 'quiz-ai-knowledge', 'What does ''AI ethics'' primarily address?', '["Maximising the speed of AI computations","Ensuring AI systems are developed and used responsibly and fairly","Reducing the cost of AI hardware","Increasing the number of parameters in models"]', 1, 'AI ethics is concerned with the moral implications of AI development and deployment, including fairness, transparency, accountability, and privacy.', 'beginner', '["governance-responsible-ai"]'), ('qq-b-12', 'quiz-ai-knowledge', 'Which of these is a type of generative AI model?', '["Decision tree","Diffusion model","Linear regression","K-means clustering"]', 1, 'Diffusion models are a class of generative AI that learn to generate data by reversing a gradual noising process, commonly used for image generation.', 'beginner', '["llms-generative-ai","ai-foundations"]'), ('qq-b-13', 'quiz-ai-knowledge', 'What is ''data privacy'' in AI?', '["Making AI models open-source","Protecting personal information used in AI systems","Increasing dataset sizes","Sharing data across all AI companies"]', 1, 'Data privacy in AI involves protecting sensitive personal information collected, processed, and stored by AI systems, often governed by regulations like GDPR.', 'beginner', '["governance-responsible-ai"]'), ('qq-b-14', 'quiz-ai-knowledge', 'What does ''unsupervised learning'' do?', '["Learns from labelled data with known answers","Discovers hidden patterns in data without predefined labels","Requires constant human supervision during training","Only works with image data"]', 1, 'Unsupervised learning algorithms analyse and cluster unlabelled datasets, discovering hidden patterns or groupings without explicit guidance.', 'beginner', '["data-ml"]'), ('qq-b-15', 'quiz-ai-knowledge', 'Which of these is a real-world application of computer vision?', '["Generating random passwords","Facial recognition in smartphones","Sorting email spam","Compressing video files"]', 1, 'Computer vision enables machines to derive meaningful information from digital images and videos; facial recognition is a prominent real-world application.', 'beginner', '["ai-foundations","data-ml"]'), ('qq-i-01', 'quiz-ai-knowledge', 'What is the ''attention mechanism'' in transformer models?', '["A method to reduce model size","A technique allowing the model to focus on relevant parts of the input when producing output","A way to speed up CPU processing","A regularisation technique to prevent overfitting"]', 1, 'The attention mechanism enables transformers to weigh the importance of different input tokens dynamically, improving context understanding in sequences.', 'intermediate', '["llms-generative-ai"]'), ('qq-i-02', 'quiz-ai-knowledge', 'What is ''few-shot prompting''?', '["Training a model with only a few parameters","Providing a language model with a small number of examples within the prompt to guide its output","Running a model for a short duration","Using a dataset with minimal preprocessing"]', 1, 'Few-shot prompting includes a small number of input-output examples in the prompt, helping the model understand the desired task format without fine-tuning.', 'intermediate', '["prompt-engineering","llms-generative-ai"]'), ('qq-i-03', 'quiz-ai-knowledge', 'What is ''gradient descent'' used for in neural networks?', '["Generating training data","Optimising model weights to minimise loss","Compressing the model for deployment","Converting text to numerical vectors"]', 1, 'Gradient descent is an optimisation algorithm that iteratively adjusts a model''s weights in the direction that reduces the loss function.', 'intermediate', '["data-ml"]'), ('qq-i-04', 'quiz-ai-knowledge', 'What is ''prompt injection'' in the context of LLMs?', '["Adding more tokens to increase output length","A security attack where malicious input manipulates the model''s behaviour","Injecting training data into the model weights","A method for improving translation accuracy"]', 1, 'Prompt injection is an attack where adversarial text in the input causes an LLM to ignore its original instructions and follow the injected commands.', 'intermediate', '["prompt-engineering","governance-responsible-ai","llms-generative-ai"]'), ('qq-i-05', 'quiz-ai-knowledge', 'What does ''backpropagation'' do?', '["Forwards data through the network","Calculates gradients of the loss with respect to each weight by applying the chain rule backwards","Initialises random weights before training","Compresses the neural network for faster inference"]', 1, 'Backpropagation computes gradients by propagating the error backwards through the network, enabling efficient weight updates during training.', 'intermediate', '["data-ml"]');
INSERT INTO quiz_questions (id, quiz_id, question_text, options_json, correct_index, explanation, difficulty, topic_tags_json) VALUES ('qq-i-06', 'quiz-ai-knowledge', 'Which technique improves LLM reasoning by encouraging step-by-step thinking?', '["Zero-shot prompting","Chain-of-thought prompting","Temperature sampling","Token masking"]', 1, 'Chain-of-thought prompting guides the model to break down problems into intermediate reasoning steps, significantly improving performance on complex tasks.', 'intermediate', '["prompt-engineering","llms-generative-ai"]'), ('qq-i-07', 'quiz-ai-knowledge', 'What is ''transfer learning'' in machine learning?', '["Moving data between cloud servers","Using a pre-trained model on a new, related task with minimal additional training","Transferring weights manually between layers","Learning from one dataset and discarding it before the next"]', 1, 'Transfer learning leverages knowledge gained from solving one problem and applies it to a different but related problem, reducing training time and data requirements.', 'intermediate', '["data-ml","llms-generative-ai"]'), ('qq-i-08', 'quiz-ai-knowledge', 'What is an ''AI agent'' in modern systems?', '["A human customer service representative","An autonomous system that perceives its environment and takes actions to achieve goals","A static database of AI research papers","A physical robot only used in factories"]', 1, 'An AI agent is an autonomous entity that observes its environment through sensors and acts upon it using actuators to achieve specific objectives.', 'intermediate', '["ai-agents"]'), ('qq-i-09', 'quiz-ai-knowledge', 'What does ''tokenisation'' mean in NLP?', '["Encrypting text for secure transmission","Splitting text into smaller units (tokens) that a model can process","Removing stop words from a document","Translating text between languages"]', 1, 'Tokenisation is the process of breaking text into individual tokens (words, subwords, or characters) that serve as the basic input units for language models.', 'intermediate', '["llms-generative-ai","prompt-engineering"]'), ('qq-i-10', 'quiz-ai-knowledge', 'Which EU regulation specifically addresses AI risk classification?', '["GDPR","AI Act","Digital Services Act","Net Neutrality Directive"]', 1, 'The EU AI Act classifies AI systems by risk level (minimal, limited, high, unacceptable) and imposes corresponding compliance obligations.', 'intermediate', '["governance-responsible-ai"]'), ('qq-i-11', 'quiz-ai-knowledge', 'What is ''reinforcement learning from human feedback'' (RLHF)?', '["A method where humans directly code the model''s weights","Training a model using human preferences to reward or penalise outputs","A technique to reduce model size through human review","A way to manually label every training example"]', 1, 'RLHF trains models by collecting human preferences on outputs and using reinforcement learning to optimise the model to produce preferred responses.', 'intermediate', '["llms-generative-ai","data-ml"]'), ('qq-i-12', 'quiz-ai-knowledge', 'What is ''model drift'' in production ML systems?', '["The physical movement of servers","Degradation of model performance over time due to changes in input data distribution","A technique to animate 3D models","Random fluctuations in training loss"]', 1, 'Model drift (or data drift) occurs when the statistical properties of the target variable change over time in unforeseen ways, causing the model''s accuracy to degrade.', 'intermediate', '["data-ml","governance-responsible-ai"]'), ('qq-i-13', 'quiz-ai-knowledge', 'What is the primary role of the ''encoder'' in a transformer?', '["Generating output sequences","Processing input sequences into contextual representations","Storing training data","Optimising hyperparameters"]', 1, 'The encoder in a transformer architecture processes the input sequence and produces contextualised representations that capture relationships between tokens.', 'intermediate', '["llms-generative-ai"]'), ('qq-i-14', 'quiz-ai-knowledge', 'What does ''explainable AI'' (XAI) aim to achieve?', '["Making AI models run faster","Making AI decision-making processes understandable to humans","Reducing the cost of AI training","Creating AI that can explain concepts to other AI"]', 1, 'Explainable AI focuses on creating models and techniques that make the reasoning behind AI decisions transparent and interpretable to human users.', 'intermediate', '["governance-responsible-ai"]'), ('qq-i-15', 'quiz-ai-knowledge', 'What is ''dropout'' in neural networks?', '["Removing the final layer of the network","A regularisation technique that randomly deactivates neurons during training","A method to delete training data","Stopping training early to save energy"]', 1, 'Dropout is a regularisation technique where randomly selected neurons are ignored during training, preventing the network from becoming too dependent on specific paths and reducing overfitting.', 'intermediate', '["data-ml"]');
INSERT INTO quiz_questions (id, quiz_id, question_text, options_json, correct_index, explanation, difficulty, topic_tags_json) VALUES ('qq-a-01', 'quiz-ai-knowledge', 'What is the ''vanishing gradient problem'' in deep neural networks?', '["Gradients become too large and cause numerical overflow","Gradients shrink exponentially in early layers during backpropagation, preventing effective learning","The model forgets previously learned patterns","The loss function becomes constant and stops changing"]', 1, 'In deep networks with certain activation functions (like sigmoid), gradients can become vanishingly small as they propagate backwards, making it difficult to train early layers.', 'advanced', '["data-ml"]'), ('qq-a-02', 'quiz-ai-knowledge', 'In the context of LLM safety, what is ''jailbreaking''?', '["Unlocking a model''s weights for open-source use","Crafting prompts that bypass safety guardrails to elicit harmful outputs","Removing encryption from model files","Training a model without any constraints"]', 1, 'Jailbreaking refers to adversarial prompt engineering designed to circumvent an LLM''s safety alignment and elicit responses that violate usage policies.', 'advanced', '["governance-responsible-ai","llms-generative-ai","prompt-engineering"]'), ('qq-a-03', 'quiz-ai-knowledge', 'What distinguishes a ''Mixture of Experts'' (MoE) architecture from dense transformers?', '["MoE uses only convolutional layers","MoE activates a subset of specialised expert networks per token rather than all parameters","MoE requires less total memory than dense models","MoE cannot handle sequential data"]', 1, 'Mixture of Experts architectures use sparse activation: for each input token, only a small subset of expert networks is activated, enabling massive scale without proportional compute cost.', 'advanced', '["llms-generative-ai","data-ml"]'), ('qq-a-04', 'quiz-ai-knowledge', 'What is ''mechanistic interpretability'' in AI research?', '["Making AI models faster through hardware optimisation","Reverse-engineering neural networks to understand how specific computations are implemented","Creating AI that can interpret legal documents","Translating model outputs into multiple languages"]', 1, 'Mechanistic interpretability seeks to reverse-engineer the internal algorithms of neural networks, identifying which circuits and neurons perform specific tasks.', 'advanced', '["governance-responsible-ai","llms-generative-ai"]'), ('qq-a-05', 'quiz-ai-knowledge', 'What is ''adversarial robustness'' in machine learning?', '["The ability to train on adversarial examples only","Resistance of a model to performance degradation from carefully crafted input perturbations","Training models to compete against each other","Using hostile datasets to improve generalisation"]', 1, 'Adversarial robustness measures how well a model maintains correct predictions when inputs are perturbed with small, intentional modifications designed to cause misclassification.', 'advanced', '["governance-responsible-ai","data-ml"]'), ('qq-a-06', 'quiz-ai-knowledge', 'What is the primary limitation of autoregressive language models?', '["They cannot process text longer than 100 tokens","They generate tokens left-to-right and cannot revise earlier decisions","They require labelled data for every token","They can only work with English text"]', 1, 'Autoregressive models generate sequences token by token from left to right. Once a token is generated, it cannot be revised, which can lead to compounding errors in long outputs.', 'advanced', '["llms-generative-ai"]'), ('qq-a-07', 'quiz-ai-knowledge', 'What does ''constitutional AI'' aim to do?', '["Embed national laws directly into model weights","Train AI systems using a set of principles (a constitution) to self-critique and improve harmlessness","Limit AI development to government-approved organisations","Require AI models to have a physical constitution document"]', 1, 'Constitutional AI, developed by Anthropic, trains models to critique their own outputs against a set of principles and revise them to be more helpful, honest, and harmless.', 'advanced', '["governance-responsible-ai","llms-generative-ai"]'), ('qq-a-08', 'quiz-ai-knowledge', 'What is ''quantisation'' in the context of deploying LLMs?', '["Reducing the number of training epochs","Converting model weights from high-precision formats (e.g., FP32) to lower-precision (e.g., INT8) to reduce size and latency","Dividing the dataset into smaller batches","Compressing text input before tokenisation"]', 1, 'Quantisation reduces the precision of model weights, significantly decreasing memory footprint and inference latency with minimal accuracy loss.', 'advanced', '["llms-generative-ai","data-ml"]'), ('qq-a-09', 'quiz-ai-knowledge', 'What is ''speculative decoding'' used for?', '["Guessing the user''s next prompt","Accelerating LLM inference by using a smaller draft model to predict tokens verified by the main model","Decrypting encoded model outputs","Predicting stock market trends from news"]', 1, 'Speculative decoding speeds up inference by having a smaller, faster draft model generate candidate tokens that the larger target model verifies in parallel, accepting or rejecting them.', 'advanced', '["llms-generative-ai"]'), ('qq-a-10', 'quiz-ai-knowledge', 'Which attack targets LLMs by manipulating retrieval-augmented generation (RAG) document stores?', '["SQL injection","Prompt injection","Data poisoning in the retrieval corpus","Cross-site scripting"]', 2, 'In RAG systems, attackers can poison the retrieval corpus with malicious documents that the LLM then retrieves and cites, causing it to generate harmful or incorrect outputs.', 'advanced', '["governance-responsible-ai","llms-generative-ai"]');
INSERT INTO quiz_questions (id, quiz_id, question_text, options_json, correct_index, explanation, difficulty, topic_tags_json) VALUES ('qq-a-11', 'quiz-ai-knowledge', 'What is the ''alignment problem'' in AI?', '["Aligning model weights in parallel GPU arrays","Ensuring AI systems act in accordance with human values and intended goals","Aligning text embeddings to a common vector space","Synchronising distributed training nodes"]', 1, 'The alignment problem refers to the challenge of ensuring AI systems pursue the objectives their designers actually intended, rather than optimising for proxy metrics in harmful ways.', 'advanced', '["governance-responsible-ai","ai-foundations"]'), ('qq-a-12', 'quiz-ai-knowledge', 'What is ''LoRA'' (Low-Rank Adaptation) used for?', '["Increasing model parameter count","Efficiently fine-tuning large models by training small low-rank matrices instead of all weights","Compressing training datasets","Optimising SQL queries for ML pipelines"]', 1, 'LoRA freezes pre-trained model weights and injects trainable rank decomposition matrices into each layer, enabling efficient fine-tuning with far fewer trainable parameters.', 'advanced', '["data-ml","llms-generative-ai"]'), ('qq-a-13', 'quiz-ai-knowledge', 'What does ''stochastic parrot'' critique argue about LLMs?', '["LLMs are truly conscious beings","LLMs generate plausible text by statistical pattern matching without understanding meaning","LLMs are too random to be useful","LLMs can only repeat training data verbatim"]', 1, 'The stochastic parrot critique, notably by Bender et al. (2021), argues that LLMs produce coherent text through statistical pattern matching without genuine comprehension, grounding, or understanding of meaning.', 'advanced', '["llms-generative-ai","governance-responsible-ai"]'), ('qq-a-14', 'quiz-ai-knowledge', 'What is a ''world model'' in the context of AI agents?', '["A 3D map of every country","An internal representation that allows an agent to predict the consequences of its actions in an environment","A database of Wikipedia articles","A graphical user interface for AI systems"]', 1, 'A world model is an agent''s internal representation of its environment, enabling it to simulate outcomes, plan sequences of actions, and learn from imagined scenarios.', 'advanced', '["ai-agents","ai-foundations"]'), ('qq-a-15', 'quiz-ai-knowledge', 'What is ''differential privacy'' designed to protect?', '["Model weights from being stolen","Individual data contributions in aggregated datasets from being identified","AI systems from physical damage","Training data from being deleted"]', 1, 'Differential privacy is a mathematical framework that ensures the output of a computation reveals almost nothing about any individual record in the dataset, protecting privacy even when data is aggregated.', 'advanced', '["governance-responsible-ai","data-ml"]');
